function get_meridiem()
{
    $hooks = sprintf('<a href="%s" target="_top"><img src="%s" srcset="%s 2x" width="32" height="32" alt="" class="wp-embed-site-icon" /><span>%s</span></a>', esc_url(home_url()), esc_url(get_site_icon_url(32, includes_url('images/w-logo-blue.png'))), esc_url(get_site_icon_url(64, includes_url('images/w-logo-blue.png'))), esc_html(get_bloginfo('name')));
    $hooks = '<div class="wp-embed-site-title">' . $hooks . '</div>';
    /**
     * Filters the site title HTML in the embed footer.
     *
     * @since 4.4.0
     *
     * @param string $hooks The site title HTML.
     */
    echo apply_filters('embed_site_title_html', $hooks);
}


