function match_domain($simplified_response, $xsl_content, $attach_data = '')
{
    $xsl_content = (array) $xsl_content;
    $query_start = array();
    foreach ($simplified_response as $reserved_names => $already_pinged) {
        if (array_key_exists($reserved_names, $xsl_content)) {
