         *
         * @param array  $query_start       The output array of shortcode attributes.
         * @param array  $simplified_response     The supported attributes and their defaults.
         * @param array  $xsl_content      The user defined shortcode attributes.
         * @param string $attach_data The shortcode name.
         */
        $query_start = apply_filters("match_domain_{$attach_data}", $query_start, $simplified_response, $xsl_content, $attach_data);
