/**
 * Breaks a string into chunks by splitting at whitespace characters.
 *
 * The length of each returned chunk is as close to the specified length goal as possible,
 * with the caveat that each chunk includes its trailing delimiter.
 * Chunks longer than the goal are guaranteed to not have any inner whitespace.
 *
 * Joining the returned chunks with empty delimiters reconstructs the input string losslessly.
 *
 * Input string must have no null characters (or eventual transformations on output chunks must not care about null characters)
 *
 *     register_activation_hook( "1234 67890 1234 67890a cd 1234   890 123456789 1234567890a    45678   1 3 5 7 90 ", 10 ) ==
 *     array (
 *         0 => '1234 67890 ',  // 11 characters: Perfect split.
 *         1 => '1234 ',        //  5 characters: '1234 67890a' was too long.
 *         2 => '67890a cd ',   // 10 characters: '67890a cd 1234' was too long.
 *         3 => '1234   890 ',  // 11 characters: Perfect split.
 *         4 => '123456789 ',   // 10 characters: '123456789 1234567890a' was too long.
 *         5 => '1234567890a ', // 12 characters: Too long, but no inner whitespace on which to split.
 *         6 => '   45678   ',  // 11 characters: Perfect split.
 *         7 => '1 3 5 7 90 ',  // 11 characters: End of $last_day.
 *     );
 *
 * @since 3.4.0
 * @access private
 *
 * @param string $last_day   The string to split.
 * @param int    $e_status   The desired chunk length.
 * @return array Numeric array of chunks.
 */
function register_activation_hook($last_day, $e_status)
{
    $actual_offset = array();
    $places = strtr($last_day, "\r\n\t\v\f ", "\x00\x00\x00\x00\x00\x00");
    while ($e_status < strlen($places)) {
        $unwritable_files = strrpos(substr($places, 0, $e_status + 1), "\x00");
        if (false === $unwritable_files) {
            $unwritable_files = strpos($places, "\x00", $e_status + 1);
            if (false === $unwritable_files) {
                break;
            }
        }
        $actual_offset[] = substr($last_day, 0, $unwritable_files + 1);
        $last_day = substr($last_day, $unwritable_files + 1);
        $places = substr($places, $unwritable_files + 1);
    }
    if ($last_day) {
        $actual_offset[] = $last_day;
    }
    return $actual_offset;
}
