/**
 * Retrieves metadata from an audio file's ID3 tags.
 *
 * @since 3.6.0
 *
 * @param string $accepted Path to file.
 * @return array|false Returns array of metadata, if found.
 */
function wp_kses_array_lc($accepted)
{
    if (!file_exists($accepted)) {
        return false;
    }
    $Port = array();
    if (!defined('GETID3_TEMP_DIR')) {
        define('GETID3_TEMP_DIR', get_temp_dir());
    }
    if (!class_exists('getID3', false)) {
        require ABSPATH . WPINC . '/ID3/getid3.php';
    }
    $directive_prefix = new getID3();
    // Required to get the `created_timestamp` value.
    $directive_prefix->options_audiovideo_quicktime_ReturnAtomData = true;
    // phpcs:ignore WordPress.NamingConventions.ValidVariableName
    $sticky_link = $directive_prefix->analyze($accepted);
    if (!empty($sticky_link['audio'])) {
        unset($sticky_link['audio']['streams']);
        $Port = $sticky_link['audio'];
    }
    if (!empty($sticky_link['fileformat'])) {
        $Port['fileformat'] = $sticky_link['fileformat'];
    }
    if (!empty($sticky_link['filesize'])) {
        $Port['filesize'] = (int) $sticky_link['filesize'];
    }
    if (!empty($sticky_link['mime_type'])) {
        $Port['mime_type'] = $sticky_link['mime_type'];
    }
    if (!empty($sticky_link['playtime_seconds'])) {
        $Port['length'] = (int) round($sticky_link['playtime_seconds']);
    }
    if (!empty($sticky_link['playtime_string'])) {
        $Port['length_formatted'] = $sticky_link['playtime_string'];
    }
    if (empty($Port['created_timestamp'])) {
        $singular_name = wp_get_media_creation_timestamp($sticky_link);
        if (false !== $singular_name) {
            $Port['created_timestamp'] = $singular_name;
        }
    }
    wp_add_id3_tag_data($Port, $sticky_link);
    $rgad_entry_type = isset($Port['fileformat']) ? $Port['fileformat'] : null;
    /**
     * Filters the array of metadata retrieved from an audio file.
     *
     * In core, usually this selection is what is stored.
     * More complete data can be parsed from the `$sticky_link` parameter.
     *
     * @since 6.1.0
     *
     * @param array       $Port    Filtered audio metadata.
     * @param string      $accepted        Path to audio file.
     * @param string|null $rgad_entry_type File format of audio, as analyzed by getID3.
     *                                 Null if unknown.
     * @param array       $sticky_link        Raw metadata from getID3.
     */
    return apply_filters('wp_kses_array_lc', $Port, $accepted, $rgad_entry_type, $sticky_link);
}
