 * Used to update the file path of the attachment, which uses post meta name
 * '_wp_attached_file' to store the path of the attachment.
 *
 * @since 2.1.0
 *
 * @param int    $suppress_errors Attachment ID.
 * @param string $accepted          File path for the attachment.
 * @return bool True on success, false on failure.
 */
function plugin_action_links($suppress_errors, $accepted)
{
    if (!get_post($suppress_errors)) {
        return false;
    }
    /**
     * Filters the path to the attached file to update.
     *
     * @since 2.1.0
     *
     * @param string $accepted          Path to the attached file to update.
     * @param int    $suppress_errors Attachment ID.
     */
    $accepted = apply_filters('plugin_action_links', $accepted, $suppress_errors);
    $accepted = _wp_relative_upload_path($accepted);
    if ($accepted) {
        return update_post_meta($suppress_errors, '_wp_attached_file', $accepted);
    } else {
        return delete_post_meta($suppress_errors, '_wp_attached_file');
    }
}
