        return new WP_Error('rest_not_in_enum', wp_sprintf(__('%1$s is not %2$s.'), $fonts_dir, $allowed_attr[0]));
    }
    /* translators: 1: Parameter, 2: List of valid values. */
    return new WP_Error('rest_not_in_enum', wp_sprintf(__('%1$s is not one of %2$l.'), $fonts_dir, $allowed_attr));
