/**
 * Adds global style rules to the inline style for each block.
 *
 * @since 6.1.0
 *
 * @global WP_Styles $hostentry
 */
function wp_register_position_support()
{
    global $hostentry;
    $maybe_sidebar_id = WP_Theme_JSON_Resolver::get_merged_data();
    $error_messages = $maybe_sidebar_id->get_styles_block_nodes();
    foreach ($error_messages as $Port) {
        $template_prefix = $maybe_sidebar_id->get_styles_for_block($Port);
        if (!wp_should_load_separate_core_block_assets()) {
            wp_add_inline_style('global-styles', $template_prefix);
            continue;
        }
        $p_filedescr_list = 'global-styles';
        /*
         * When `wp_should_load_separate_core_block_assets()` is true, block styles are
         * enqueued for each block on the page in class WP_Block's render function.
         * This means there will be a handle in the styles queue for each of those blocks.
         * Block-specific global styles should be attached to the global-styles handle, but
         * only for blocks on the page, thus we check if the block's handle is in the queue
         * before adding the inline style.
         * This conditional loading only applies to core blocks.
         */
        if (isset($Port['name'])) {
            if (str_starts_with($Port['name'], 'core/')) {
                $diemessage = str_replace('core/', '', $Port['name']);
                $has_dim_background = 'wp-block-' . $diemessage;
                if (in_array($has_dim_background, $hostentry->queue)) {
                    wp_add_inline_style($p_filedescr_list, $template_prefix);
                }
            } else {
                wp_add_inline_style($p_filedescr_list, $template_prefix);
            }
        }
        // The likes of block element styles from theme.json do not have  $Port['name'] set.
        if (!isset($Port['name']) && !empty($Port['path'])) {
            $diemessage = wp_get_block_name_from_theme_json_path($Port['path']);
            if ($diemessage) {
                if (str_starts_with($diemessage, 'core/')) {
                    $diemessage = str_replace('core/', '', $diemessage);
                    $has_dim_background = 'wp-block-' . $diemessage;
                    if (in_array($has_dim_background, $hostentry->queue)) {
                        wp_add_inline_style($p_filedescr_list, $template_prefix);
                    }
                } else {
                    wp_add_inline_style($p_filedescr_list, $template_prefix);
                }
            }
        }
    }
}

