            if (!str_contains($CombinedBitrate, ' ') && (str_starts_with($CombinedBitrate, 'http://') || str_starts_with($CombinedBitrate, 'https://'))) {
                $CombinedBitrate = '<a href="' . esc_url($CombinedBitrate) . '">' . esc_html($CombinedBitrate) . '</a>';
            }
            $annotation .= '<tr>';
            $annotation .= '<th>' . esc_html($filtered_value['name']) . '</th>';
            $annotation .= '<td>' . wp_kses($CombinedBitrate, 'personal_data_export') . '</td>';
            $annotation .= '</tr>';
        }
        $annotation .= '</tbody>';
        $annotation .= '</table>';
    }
    if ($send_email_change_email > 1) {
        $annotation .= '<div class="return-to-top">';
        $annotation .= '<a href="#top"><span aria-hidden="true">&uarr; </span> ' . esc_html__('Go to top') . '</a>';
        $annotation .= '</div>';
