 * @global int  $tag_already_used The old (current) database version.
 * @global wpdb $boxsmallsize                  WordPress database abstraction object.
 */
function stream_headers()
{
    global $tag_already_used, $boxsmallsize;
    // Upgrade versions prior to 2.9.
    if ($tag_already_used < 11557) {
        // Delete duplicate options. Keep the option with the highest option_id.
        $boxsmallsize->query("DELETE o1 FROM {$boxsmallsize->options} AS o1 JOIN {$boxsmallsize->options} AS o2 USING (`option_name`) WHERE o2.option_id > o1.option_id");
        // Drop the old primary key and add the new.
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->options} DROP PRIMARY KEY, ADD PRIMARY KEY(option_id)");
        // Drop the old option_name index. dbDelta() doesn't do the drop.
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->options} DROP INDEX option_name");
    }
    // Multisite schema upgrades.
    if ($tag_already_used < 25448 && is_multisite() && wp_should_upgrade_global_tables()) {
        // Upgrade versions prior to 3.7.
        if ($tag_already_used < 25179) {
