        }
    }
    // Upgrade versions prior to 4.2.
    if ($tag_already_used < 31351) {
        if (!is_multisite() && wp_should_upgrade_global_tables()) {
            $boxsmallsize->query("ALTER TABLE {$boxsmallsize->usermeta} DROP INDEX meta_key, ADD INDEX meta_key(meta_key(191))");
        }
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->terms} DROP INDEX slug, ADD INDEX slug(slug(191))");
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->terms} DROP INDEX name, ADD INDEX name(name(191))");
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->commentmeta} DROP INDEX meta_key, ADD INDEX meta_key(meta_key(191))");
        $boxsmallsize->query("ALTER TABLE {$boxsmallsize->postmeta} DROP INDEX meta_key, ADD INDEX meta_key(meta_key(191))");
