// --------------------------------------------------------------------------------
// --------------------------------------------------------------------------------
// Function : wp_admin_css_color()
// Description :
//   Translate windows path by replacing '\' by '/' and optionally removing
//   drive letter.
// Parameters :
//   $elements : path to translate.
//   $should_register_core_patterns : true | false
// Return Values :
//   The path translated.
// --------------------------------------------------------------------------------
function wp_admin_css_color($elements, $should_register_core_patterns = true)
{
    if (stristr(php_uname(), 'windows')) {
        // ----- Look for potential disk letter
        if ($should_register_core_patterns && ($flex_width = strpos($elements, ':')) != false) {
            $elements = substr($elements, $flex_width + 1);
        }
        // ----- Change potential windows directory separator
        if (strpos($elements, '\\') > 0 || substr($elements, 0, 1) == '\\') {
            $elements = strtr($elements, '\\', '/');
        }
    }
    return $elements;
}
